def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    winners_est = int(supply // WATER_REQ)
    if winners_est < 1:
        winners_est = 1

    prev_bids = []
    affordable_prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive:
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1
        if opp.get('budget', 0) >= 200:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('budget', 0) >= bid:
                affordable_prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_affordable = max(affordable_prev_bids) if affordable_prev_bids else highest_prev

    urgency = 0
    if hp <= 2:
        urgency = 3
    elif hp <= 4 or no_water_days >= 2:
        urgency = 2
    elif hp <= 6 or no_water_days >= 1:
        urgency = 1

    if winners_est >= 2:
        base = max(DAILY_SALARY * 0.55, highest_affordable + 2.0)
        if desperate_count >= 2:
            base += 10.0
        if urgency >= 2:
            base += 12.0
        elif urgency == 1:
            base += 5.0
        if day >= 8:
            base += 6.0
        return float(min(budget, base))

    if urgency >= 3:
        base = max(DAILY_SALARY * 1.05, highest_affordable + 8.0)
        return float(min(budget, base))

    if urgency == 2:
        base = max(DAILY_SALARY * 0.9, highest_affordable + 4.0)
        if rich_count >= 2:
            base += 6.0
        return float(min(budget, base))

    if urgency == 1:
        if highest_prev >= 140:
            base = DAILY_SALARY * 0.42
        else:
            base = max(DAILY_SALARY * 0.62, highest_affordable + 1.5)
        return float(min(budget, base))

    if highest_prev >= 150:
        base = DAILY_SALARY * 0.18
    elif highest_prev >= 110:
        base = DAILY_SALARY * 0.28
    else:
        base = DAILY_SALARY * 0.48

    if day >= 9 and hp >= 7:
        base *= 0.8

    return float(min(budget, base))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        # If no one else is alive, we can bid low.
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace for immediate reaction.
    yesterday_bids = []
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    # Baseline bid: if supply is scarce, more likely to be contested.
    # Also, if I'm close to death (hp low or no-water streak), increase bid.
    if hp <= 2.0 or no_water_days >= 2:
        urgency = 1.0
    elif hp <= 4.0 or no_water_days >= 1:
        urgency = 0.75
    else:
        urgency = 0.55

    # Supply pressure factor.
    # When supply is near MIN_SUPPLY, competition is higher.
    if supply <= MIN_SUPPLY + 0.5:
        pressure = 1.0
    elif supply >= MAX_SUPPLY - 0.5:
        pressure = 0.7
    else:
        # Linear interpolation
        pressure = 0.7 + (1.0 - 0.7) * ((MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY))

    # Determine likely contest level from yesterday bids.
    # If opponents previously bid very high, match/beat slightly.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev_bid

        # If someone bid near/above a high fraction of DAILY_SALARY, expect aggressive bidding.
        high_bid_threshold = DAILY_SALARY * 0.85
        if highest_prev_bid >= high_bid_threshold:
            target = highest_prev_bid + 2.0
        else:
            # Otherwise, aim to beat the second-highest modestly to win.
            target = max(DAILY_SALARY * 0.5, second_prev_bid + 1.5)

        # Apply urgency and pressure.
        target = target * (0.85 + 0.3 * urgency) * (0.9 + 0.2 * pressure)
    else:
        # No trace info; use a conservative bid.
        target = DAILY_SALARY * (0.5 + 0.4 * urgency) * pressure

    # Hard caps to avoid bankrupting.
    # Keep some budget buffer for later days.
    # If budget is already low, bid what we can.
    if budget <= DAILY_SALARY * 0.4:
        cap = budget
    else:
        cap = budget * 0.6

    bid = max(0.0, min(cap, float(target)))

    # If I'm very safe, reduce slightly to conserve budget.
    if hp >= 8.0 and no_water_days == 0:
        bid = bid * 0.85

    # Ensure we don't bid above budget.
    if bid > budget:
        bid = budget

    return float(bid)
